messages.content:
Tool response:
Tool: find_tissue_specimens
Description: Find Tissue Specimens
Parameters:
    {
      "type": "object",
      "properties": {
        "donor_code": {
          "type": "string",
          "description": "Donor code to filter specimens",
          "title": "Donor Code"
        },
        "protocol_code": {
          "type": "string",
          "description": "Protocol code used for processing specimens",
          "title": "Protocol Code"
        },
        "tank_codes": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "List of tank codes where specimens are stored",
          "title": "Tank Codes"
        },
        "min_viability": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "description": "Minimum viability percentage threshold (default 85)",
          "default": 85.0,
          "title": "Min Viability"
        }
      },
      "required": [
        "donor_code",
        "protocol_code",
        "tank_codes"
      ]
    }
